@Component("catalog-handler")
@ProcessingGroup("catalog-processing-group")
public class CatalogEventHandler {
	
	// core constructor
	CatalogEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateCatalogEvent
     */
    @EventHandler
    public void handle( CreateCatalogEvent event) {
        entityManager.persist(new Catalog(event.getCatalogId(), event.getName(), event.getCatalogCode(), event.getAsActive(), event.getChannel(), event.getCategories()));
    }

    /*
     * @param	event UpdateCatalogEvent
     */
    @EventHandler
    public Catalog handle( UpdateCatalogEvent event) {
    	entityManager.merge(new Catalog(event.getCatalogId(), event.getName(), event.getCatalogCode(), event.getAsActive(), event.getChannel(), event.getCategories()));
    }
    
    /*
     * @param	event DeleteCatalogEvent
     */
    @EventHandler
    public void on( DeleteCatalogEvent event) {
    	Catalog entity = new Catalog();
   
    	// ------------------------------------------
    	// apply the CatalogId
    	// ------------------------------------------
    	entity.setCatalogId( event.getCatalogId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final CatalogRepository catalogEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(CatalogEventHandler.class.getName());

}
